    nao_tem_plano_de_saude: 'Não tem plano de saúde',
    nao_gostou_do_hospital: 'Não gostou do hospital',
    sus: 'SUS',
    outro: 'Outro(s)',
  },
};

function toLabel(field, value) {
  if (value === null || value === undefined || value === '') return null;
  const map = LABELS[field];
  if (!map) return value;
  return map[value] || value;
}

const output = [];

for (const item of $input.all()) {
  const d = item.json;

  output.push({
    json: {
      // Identificadores
      conversation_id: d.conversation_id,
      contact_name: d.contact_name,
      data_nascimento: d.data_nascimento,
      email: d.email,
      phone: d.phone,

      // Campos traduzidos para o Chatwoot
      assunto_label: toLabel('assunto', d.assunto),
      para_quem_label: toLabel('para_quem', d.para_quem),
      tipo_contato_label: toLabel('tipo_contato', d.tipo_contato),
      motivo_contato_label: toLabel('motivo_contato', d.motivo_contato),
      forma_internacao_label: toLabel('forma_internacao', d.forma_internacao),
      plano_saude_label: toLabel('plano_saude', d.plano_saude),
      estagio_funil_label: toLabel('estagio_funil', d.estagio_funil),
      status_label: toLabel('status', d.status),
      motivo_desqualificacao_label: toLabel('motivo_desqualificacao', d.motivo_desqualificacao),
      motivo_perda_label: toLabel('motivo_perda', d.motivo_perda),

      // Booleans e demais
      ex_paciente: d.ex_paciente,
      carteirinha_enviada: d.carteirinha_enviada,
      carteirinha_url: d.carteirinha_url,
      observacoes: d.observacoes,
      elegivel: d.elegivel,
      transbordado: d.transbordado,
      tags: d.tags,
    },
  });
}

return output;

